const staticData = $getWorkflowStaticData('global');
if (!staticData.topicIds) staticData.topicIds = {};
if (!staticData.dedup) staticData.dedup = {};
if (!staticData.index) staticData.index = [];

const root = items[0].json;
const msg = root.message || root.callback_query?.message || null;
const cb = root.callback_query || null;
const text = (msg?.text || '').trim();
const chatId = msg?.chat?.id || cb?.message?.chat?.id || null;
const fromId = root.message?.from?.id || cb?.from?.id || null;

let kind = 'other';
if (cb) kind = 'callback';
else if (text === '/setup' || text.startsWith('/setup@')) kind = 'setup';
else if (text === '/start' || text.startsWith('/start@')) kind = 'start';
else if (text === '/genres' || text.startsWith('/genres@')) kind = 'genres';
else if (text.startsWith('/find')) kind = 'find';
else if (msg?.audio || (msg?.document && ((msg.document.mime_type || '').startsWith('audio/') || /\.(mp3|m4a|flac|wav|ogg|aac)$/i.test(msg.document.file_name || '')))) kind = 'media';
else if (msg?.reply_to_message && /^(переложить|положить|move)\s+(в|to)\s+/i.test(text)) kind = 'override';

return [{
  json: {
    kind,
    chatId,
    fromId,
    text,
    message: msg,
    callback: cb,
    topicIds: staticData.topicIds,
    musicGroupId: staticData.musicGroupId || null,
  }
}];

const staticData = $getWorkflowStaticData('global');
const chatId = items[0].json.chatId;
const genres = [
  { key: 'inbox', title: '📥 Inbox' },
  { key: 'hiphop', title: '🎤 Hip-Hop' },
  { key: 'house', title: '🏠 House' },
  { key: 'techno', title: '⚙️ Techno' },
  { key: 'disco', title: '🕺 Disco / Funk' },
  { key: 'other', title: '🎵 Other' },
];

staticData.musicGroupId = chatId;
if (!staticData.topicIds) staticData.topicIds = {};

const toCreate = genres.filter(g => !staticData.topicIds[g.key]);
if (!toCreate.length) {
  return [{ json: { chatId, key: null, name: null, skipCreate: true } }];
}
return toCreate.map(g => ({ json: { chatId, key: g.key, name: g.title, skipCreate: false } }));

const staticData = $getWorkflowStaticData('global');
if (!staticData.topicIds) staticData.topicIds = {};

const planned = $('Setup plan topics').all();
const httpItems = items;

if (planned.length === 1 && planned[0].json.skipCreate) {
  const lines = ['✅ Setup (n8n)', `group: ${staticData.musicGroupId}`, '', 'Топики уже есть:'];
  for (const [k, v] of Object.entries(staticData.topicIds)) lines.push(`• ${k} → ${v}`);
  lines.push('', 'Кидай трек (Hip-Hop).');
  return [{ json: { chatId: staticData.musicGroupId, text: lines.join('\n'), topicIds: staticData.topicIds } }];
}

const errors = [];
for (let i = 0; i < planned.length; i++) {
  const key = planned[i].json.key;
  if (!key) continue;
  const body = httpItems[i]?.json || {};
  const threadId = body.message_thread_id || body.result?.message_thread_id;
  if (threadId) staticData.topicIds[key] = threadId;
  else errors.push(`${key}: ${body.description || body.message || JSON.stringify(body).slice(0,120)}`);
}

const lines = ['✅ Setup (n8n)', `group: ${staticData.musicGroupId}`, '', 'Топики:'];
for (const [k, v] of Object.entries(staticData.topicIds)) lines.push(`• ${k} → ${v}`);
if (errors.length) {
  lines.push('', 'Ошибки (нужно Manage Topics у бота):');
  for (const e of errors) lines.push(`• ${e}`);
} else {
  lines.push('', 'Кидай трек для теста (Hip-Hop).');
}

return [{ json: { chatId: staticData.musicGroupId, text: lines.join('\n'), topicIds: staticData.topicIds } }];

const staticData = $getWorkflowStaticData('global');
const msg = items[0].json.message;
const chatId = items[0].json.chatId;
const audio = msg.audio;
const doc = msg.document;

const fileId = audio?.file_id || doc?.file_id;
const fileUnique = audio?.file_unique_id || doc?.file_unique_id;
const fileName = audio?.file_name || doc?.file_name || '';
const title = audio?.title || '';
const performer = audio?.performer || '';
const isAudio = Boolean(audio);

if (staticData.dedup?.[fileUnique]) {
  return [{ json: { action: 'duplicate', chatId, text: `Уже есть: ${staticData.dedup[fileUnique]}` } }];
}

const blob = `${title} ${performer} ${fileName}`.toLowerCase();
const rules = [
  [/hip[- ]?hop|\brap\b|trap|хип-?хоп|рэп/, 'hiphop', 0.9],
  [/deep house|tech house|\bhouse\b|хаус/, 'house', 0.85],
  [/techno|текно|техно/, 'techno', 0.85],
  [/nu-?disco|\bdisco\b|\bfunk\b|диско|фанк/, 'disco', 0.85],
];

let genre = 'inbox';
let confidence = 0.2;
let reason = 'no keywords';
for (const [re, key, conf] of rules) {
  if (re.test(blob)) { genre = key; confidence = conf; reason = String(re); break; }
}

const yearMatch = blob.match(/(?:19|20)\d{2}/g);
const year = yearMatch ? Number(yearMatch[yearMatch.length - 1]) : null;
let trackTitle = title;
if (!trackTitle && fileName) {
  trackTitle = fileName.replace(/\.[^.]+$/, '');
  const parts = trackTitle.split(/\s[-—–]\s/);
  if (parts.length > 1) trackTitle = parts.slice(1).join(' - ');
}
if (!trackTitle) trackTitle = 'unknown';

const topicIds = staticData.topicIds || {};
const threadId = topicIds[genre] || topicIds.inbox || null;
const needsAsk = genre === 'inbox' || confidence < 0.55;

const entry = {
  id: fileUnique || String(Date.now()),
  title: trackTitle,
  artist: performer || '',
  year,
  genre: needsAsk ? null : genre,
  fileId,
  isAudio,
  fileUnique,
};
staticData.index = (staticData.index || []).filter(x => x.id !== entry.id);
staticData.index.unshift(entry);
if (staticData.index.length > 500) staticData.index.length = 500;

if (!needsAsk && threadId) {
  staticData.dedup[fileUnique] = genre;
}

const buttons = [
  [ { text: '🎤 Hip-Hop', callback_data: `move:hiphop:${fileUnique}` }, { text: '🏠 House', callback_data: `move:house:${fileUnique}` } ],
  [ { text: '⚙️ Techno', callback_data: `move:techno:${fileUnique}` }, { text: '🕺 Disco', callback_data: `move:disco:${fileUnique}` } ],
  [ { text: '🎵 Other', callback_data: `move:other:${fileUnique}` }, { text: '📥 Inbox', callback_data: `move:inbox:${fileUnique}` } ],
];

return [{
  json: {
    action: needsAsk ? 'ask' : 'place',
    chatId,
    fileId,
    isAudio,
    fileUnique,
    genre,
    confidence,
    reason,
    threadId: needsAsk ? (topicIds.inbox || null) : threadId,
    trackTitle,
    performer,
    year,
    caption: `${genre} · ${performer ? performer + ' — ' : ''}${trackTitle}${year ? ' ('+year+')' : ''} · ${confidence}`,
    askText: needsAsk
      ? `Не уверен (${reason}). Куда положить?\n${performer ? performer + ' — ' : ''}${trackTitle}${year ? ' ('+year+')' : ''}`
      : `→ ${genre} (${confidence})\nМожно переложить кнопкой:`,
    replyMarkup: { inline_keyboard: buttons },
    topicIds,
  }
}];

const staticData = $getWorkflowStaticData('global');
const raw = (items[0].json.text || '').replace(/^\/find(@\w+)?\s*/i, '').trim();
if (!raw) {
  return [{ json: { chatId: items[0].json.chatId, text: 'Поиск:\n/find hiphop\n/find lose yourself\n/find 2010\n/find eminem 2002-2005\n\nПотом кнопкой — в папку.' } }];
}

const tokens = raw.split(/\s+/);
let genre = null;
let year = null;
let yearFrom = null;
let yearTo = null;
const textParts = [];
const genreMap = {
  hiphop: 'hiphop', 'hip-hop': 'hiphop', rap: 'hiphop', 'хипхоп': 'hiphop', 'хип-хоп': 'hiphop',
  house: 'house', хаус: 'house',
  techno: 'techno', техно: 'techno', текно: 'techno',
  disco: 'disco', funk: 'disco', диско: 'disco',
  other: 'other',
};
for (const t of tokens) {
  const low = t.toLowerCase();
  const range = low.match(/^(19|20)\d{2}[-–—](19|20)\d{2}$/);
  if (range) {
    const a = Number(low.slice(0,4)); const b = Number(low.slice(-4));
    yearFrom = Math.min(a,b); yearTo = Math.max(a,b); continue;
  }
  if (/^(19|20)\d{2}$/.test(low)) { year = Number(low); continue; }
  if (genreMap[low] && !genre) { genre = genreMap[low]; continue; }
  textParts.push(t);
}
const needle = textParts.join(' ').toLowerCase();
const hits = (staticData.index || []).filter(e => {
  if (genre && e.genre !== genre) return false;
  if (year != null && e.year !== year) return false;
  if (yearFrom != null && (e.year == null || e.year < yearFrom || e.year > yearTo)) return false;
  if (needle) {
    const hay = `${e.title} ${e.artist}`.toLowerCase();
    if (!hay.includes(needle)) return false;
  }
  return true;
}).slice(0, 8);

if (!hits.length) {
  return [{ json: { chatId: items[0].json.chatId, text: 'Пусто в индексе. Сначала кинь треки в группу (или /setup).' } }];
}

const lines = hits.map((h,i) => `${i+1}. ${h.artist ? h.artist+' — ' : ''}${h.title}${h.year ? ' ('+h.year+')' : ''}${h.genre ? ' ['+h.genre+']' : ''}`);
const top = hits[0];
staticData.pending = staticData.pending || {};
staticData.pending[top.id] = top;

return [{
  json: {
    chatId: items[0].json.chatId,
    text: `Нашёл ${hits.length}:\n\n${lines.join('\n')}\n\nТоп: ${top.title}\nВыбери папку:`,
    fileUnique: top.id,
    fileId: top.fileId,
    isAudio: top.isAudio,
  }
}];

const staticData = $getWorkflowStaticData('global');
const cb = items[0].json.callback;
const data = cb?.data || '';
const chatId = cb?.message?.chat?.id;
const parts = data.split(':');
// move:genre:fileUnique
const genre = parts[1];
const fileUnique = parts.slice(2).join(':');
const topicIds = staticData.topicIds || {};
const threadId = topicIds[genre] || topicIds.inbox || null;

let fileId = null;
let isAudio = true;
let title = fileUnique;
const fromIndex = (staticData.index || []).find(x => x.id === fileUnique || x.fileUnique === fileUnique);
const fromPending = staticData.pending?.[fileUnique];
const hit = fromIndex || fromPending;
if (hit) {
  fileId = hit.fileId;
  isAudio = hit.isAudio !== false;
  title = hit.title || title;
  hit.genre = genre;
}
if (fileUnique && genre) {
  staticData.dedup = staticData.dedup || {};
  staticData.dedup[fileUnique] = genre;
}

return [{
  json: {
    chatId,
    callbackQueryId: cb.id,
    genre,
    threadId,
    fileId,
    isAudio,
    caption: `${genre} · ${title} · manual`,
    ackText: fileId && threadId ? `Переложено → ${genre}` : `Ок: ${genre}` + (!threadId ? ' (сначала /setup)' : !fileId ? ' (нет file_id)' : ''),
  }
}];

const staticData = $getWorkflowStaticData('global');
const text = items[0].json.text || '';
const msg = items[0].json.message;
const m = text.match(/^(?:переложить|положить|move)\s+(?:в|to)\s+(.+)$/i);
const raw = (m?.[1] || '').trim().toLowerCase();
const map = { inbox:'inbox', hiphop:'hiphop','hip-hop':'hiphop', rap:'hiphop', house:'house', techno:'techno', disco:'disco', funk:'disco', other:'other', 'хип-хоп':'hiphop', хаус:'house', техно:'techno', диско:'disco', инбокс:'inbox' };
const genre = map[raw] || map[raw.replace(/\s+/g, '')] || null;
const replied = msg.reply_to_message;
const audio = replied?.audio;
const doc = replied?.document;
const fileId = audio?.file_id || doc?.file_id;
const fileUnique = audio?.file_unique_id || doc?.file_unique_id;
const isAudio = Boolean(audio);
const threadId = genre ? (staticData.topicIds || {})[genre] : null;

if (!genre) return [{ json: { chatId: items[0].json.chatId, text: 'Не знаю папку. /genres' } }];
if (!fileId) return [{ json: { chatId: items[0].json.chatId, text: 'Reply должен быть на audio/document' } }];

staticData.dedup = staticData.dedup || {};
if (fileUnique) staticData.dedup[fileUnique] = genre;

return [{
  json: {
    chatId: items[0].json.chatId,
    fileId,
    isAudio,
    threadId,
    genre,
    caption: `${genre} · override`,
    text: threadId ? `Переложено → ${genre}` : `Жанр ${genre}, но нет topic id — сначала /setup`,
  }
}];
